#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

// Fast exponentiation
int64 modpow(int64 a, int64 e) {
    int64 res = 1;
    while (e) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int r1, c1, r2, c2, r3, c3, r4, c4;
    cin >> r1 >> c1 >> r2 >> c2 >> r3 >> c3 >> r4 >> c4;

    int maxDist = 0;
    // Precompute maximum needed factorial size
    // Max coordinate difference can be up to 1e6 each, so total steps up to 2e6
    maxDist = max({abs(r2 - r1) + abs(c2 - c1),
                   abs(r4 - r3) + abs(c4 - c3),
                   abs(r2 - r1) + abs(c2 - c1) + abs(r4 - r3) + abs(c4 - c3)});
    maxDist = max(maxDist, 2000000); // safe bound

    vector<int64> fact(maxDist + 1), invfact(maxDist + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxDist; i++) fact[i] = fact[i-1] * i % MOD;
    invfact[maxDist] = modpow(fact[maxDist], MOD - 2);
    for (int i = maxDist; i > 0; i--) invfact[i-1] = invfact[i] * i % MOD;

    auto ways = [&](int x1, int y1, int x2, int y2) -> int64 {
        int dx = abs(x2 - x1);
        int dy = abs(y2 - y1);
        int n = dx + dy;
        return fact[n] * invfact[dx] % MOD * invfact[dy] % MOD;
    };

    int64 ans = 0;
    for (int lr = r1; lr <= r2; lr++) {
        for (int lc = c1; lc <= c2; lc++) {
            int64 w1 = ways(r1, c1, lr, lc);
            int64 w2 = ways(lr, lc, r3, c3);
            int64 w3 = ways(r3, c3, r4, c4);
            ans = (ans + w1 * w2 % MOD * w3) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long inv2 = (MOD + 1) / 2;

long long sum1(long long n) { // 1 + ... + n
    n %= MOD;
    return n * ((MOD + 1) / 2) % MOD;
}

long long sum2(long long n) { // 1^2 + ... + n^2
    n %= MOD;
    return n * ((n + 1) % MOD) % MOD * ((2 * n + 1) % MOD) % MOD * modpow(6, MOD - 2) % MOD;
}

// sum_{i=L}^R i
long long rangeSum1(long long L, long long R) {
    if (L > R) return 0;
    long long res = (sum1(R) - sum1(L - 1)) % MOD;
    if (res < 0) res += MOD;
    return res;
}

// sum_{i=L}^R i^2
long long rangeSum2(long long L, long long R) {
    if (L > R) return 0;
    long long res = (sum2(R) - sum2(L - 1)) % MOD;
    if (res < 0) res += MOD;
    return res;
}

// Sum over x in [A,B], y in [C,D] of |x-y|
long long sumAbs2(long long A, long long B, long long C, long long D) {
    if (A > B || C > D) return 0;
    if (B <= C) {
        long long cntX = (B - A + 1) % MOD;
        long long cntY = (D - C + 1) % MOD;
        long long sx = rangeSum1(A, B);
        long long sy = rangeSum1(C, D);
        long long res = (cntX * sy - cntY * sx) % MOD;
        if (res < 0) res += MOD;
        return res;
    }
    if (D <= A) {
        long long cntX = (B - A + 1) % MOD;
        long long cntY = (D - C + 1) % MOD;
        long long sx = rangeSum1(A, B);
        long long sy = rangeSum1(C, D);
        long long res = (cntY * sx - cntX * sy) % MOD;
        if (res < 0) res += MOD;
        return res;
    }

    // overlap case: split
    long long res = 0;

    // x in [A, min(B, C-1)], y in [C, D], contribution y-x
    if (A <= C - 1) {
        long long L = A, R = min(B, C - 1);
        long long cntX = (R - L + 1) % MOD;
        long long cntY = (D - C + 1) % MOD;
        long long sx = rangeSum1(L, R);
        long long sy = rangeSum1(C, D);
        long long add = (cntX * sy - cntY * sx) % MOD;
        if (add < 0) add += MOD;
        res += add;
        res %= MOD;
    }

    // x in [max(A,C), min(B,D)], for each x:
    // sum_{y=C}^{x} (x-y) + sum_{y=x+1}^{D} (y-x)
    long long L = max(A, C), R = min(B, D);
    if (L <= R) {
        // f(x) = (x-C)(x-C+1)/2 + (D-x)(D-x+1)/2
        // simplify:
        // = x^2 - (C+D)x + [C(C-1)+D(D+1)]/2
        long long cnt = (R - L + 1) % MOD;
        long long s1 = rangeSum1(L, R);
        long long s2 = rangeSum2(L, R);

        long long coef1 = (C + D) % MOD;
        long long cc = (( ( (__int128)C * (C - 1) ) % MOD ) + ( ( (__int128)D * (D + 1) ) % MOD )) % MOD;
        cc = cc * inv2 % MOD;

        long long add = (s2 - coef1 * s1) % MOD;
        add = (add + cnt * cc) % MOD;
        if (add < 0) add += MOD;
        res += add;
        res %= MOD;
    }

    // x in [max(A, D+1), B], y in [C, D], contribution x-y
    if (D + 1 <= B) {
        long long L2 = max(A, D + 1), R2 = B;
        long long cntX = (R2 - L2 + 1) % MOD;
        long long cntY = (D - C + 1) % MOD;
        long long sx = rangeSum1(L2, R2);
        long long sy = rangeSum1(C, D);
        long long add = (cntY * sx - cntX * sy) % MOD;
        if (add < 0) add += MOD;
        res += add;
        res %= MOD;
    }

    return res;
}

// Count pairs (s,e) with s in [A,B], e in [C,D] such that s <= e
long long countLE(long long A, long long B, long long C, long long D) {
    if (A > B || C > D) return 0;
    if (B <= C) return ((B - A + 1) % MOD) * ((D - C + 1) % MOD) % MOD;
    if (D < A) return 0;

    long long res = 0;

    // e in [max(C,A), min(D,B)]
    long long L = max(C, A), R = min(D, B);
    if (L <= R) {
        // sum_{e=L}^R (number of s in [A,B] with s<=e) = e-A+1
        long long cnt = (R - L + 1) % MOD;
        long long se = rangeSum1(L, R);
        long long add = (se - cnt * ((A - 1) % MOD)) % MOD;
        if (add < 0) add += MOD;
        res += add;
        res %= MOD;
    }

    // e in [B+1, D]
    if (B + 1 <= D) {
        long long L2 = max(C, B + 1), R2 = D;
        if (L2 <= R2) {
            long long cntE = (R2 - L2 + 1) % MOD;
            long long cntS = (B - A + 1) % MOD;
            res += cntE * cntS % MOD;
            res %= MOD;
        }
    }

    return res;
}

// For 1D intervals S=[A,B], L=[C,D], E=[E,F]
// Count triples (s,l,e) such that l is between s and e (inclusive), i.e.
// (s<=l<=e) or (e<=l<=s)
long long countBetween1D(long long A, long long B, long long C, long long D, long long E, long long F) {
    long long total = 0;

    // count s<=l<=e
    // sum over l: (#s in [A,B], s<=l) * (#e in [E,F], e>=l)
    vector<long long> pts = {C, D + 1, A, B + 1, E, F + 1};
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());

    for (int i = 0; i + 1 < (int)pts.size(); i++) {
        long long L = pts[i], R = pts[i + 1] - 1;
        if (L > R) continue;
        long long l = max(L, C), r = min(R, D);
        if (l > r) continue;

        // a(x)=#s<=x, b(x)=#e>=x
        // on this segment both are linear/constant
        // a(x):
        // 0 (x<A), x-A+1 (A<=x<=B), B-A+1 (x>B)
        // b(x):
        // F-E+1 (x<E), F-x+1 (E<=x<=F), 0 (x>F)

        auto typeA = [&](long long x)->int{
            if (x < A) return 0;
            if (x <= B) return 1;
            return 2;
        };
        auto typeB = [&](long long x)->int{
            if (x < E) return 0;
            if (x <= F) return 1;
            return 2;
        };

        int ta = typeA(l), tb = typeB(l);

        // a(x)=pa*x+qa, b(x)=pb*x+qb
        long long pa=0, qa=0, pb=0, qb=0;
        if (ta == 0) pa = 0, qa = 0;
        else if (ta == 1) pa = 1, qa = 1 - A;
        else pa = 0, qa = B - A + 1;

        if (tb == 0) pb = 0, qb = F - E + 1;
        else if (tb == 1) pb = -1, qb = F + 1;
        else pb = 0, qb = 0;

        long long cnt = (r - l + 1) % MOD;
        long long s1 = rangeSum1(l, r);
        long long s2 = rangeSum2(l, r);

        long long add = 0;
        add = (add + (pa % MOD + MOD) % MOD * ((pb % MOD + MOD) % MOD)) % MOD;
        add = add * s2 % MOD;

        long long mid = ((pa % MOD + MOD) % MOD * ((qb % MOD + MOD) % MOD) + ((pb % MOD + MOD) % MOD) * ((qa % MOD + MOD) % MOD)) % MOD;
        add = (add + mid * s1) % MOD;

        add = (add + ((qa % MOD + MOD) % MOD) * ((qb % MOD + MOD) % MOD) % MOD * cnt) % MOD;

        total += add;
        total %= MOD;
    }

    // count e<=l<=s
    vector<long long> pts2 = {C, D + 1, E, F + 1, A, B + 1};
    sort(pts2.begin(), pts2.end());
    pts2.erase(unique(pts2.begin(), pts2.end()), pts2.end());

    for (int i = 0; i + 1 < (int)pts2.size(); i++) {
        long long L = pts2[i], R = pts2[i + 1] - 1;
        if (L > R) continue;
        long long l = max(L, C), r = min(R, D);
        if (l > r) continue;

        // a(x)=#e<=x, b(x)=#s>=x
        auto typeA = [&](long long x)->int{
            if (x < E) return 0;
            if (x <= F) return 1;
            return 2;
        };
        auto typeB = [&](long long x)->int{
            if (x < A) return 0;
            if (x <= B) return 1;
            return 2;
        };

        int ta = typeA(l), tb = typeB(l);

        long long pa=0, qa=0, pb=0, qb=0;
        if (ta == 0) pa = 0, qa = 0;
        else if (ta == 1) pa = 1, qa = 1 - E;
        else pa = 0, qa = F - E + 1;

        if (tb == 0) pb = 0, qb = B - A + 1;
        else if (tb == 1) pb = -1, qb = B + 1;
        else pb = 0, qb = 0;

        long long cnt = (r - l + 1) % MOD;
        long long s1 = rangeSum1(l, r);
        long long s2 = rangeSum2(l, r);

        long long add = 0;
        add = (add + (pa % MOD + MOD) % MOD * ((pb % MOD + MOD) % MOD)) % MOD;
        add = add * s2 % MOD;

        long long mid = ((pa % MOD + MOD) % MOD * ((qb % MOD + MOD) % MOD) + ((pb % MOD + MOD) % MOD) * ((qa % MOD + MOD) % MOD)) % MOD;
        add = (add + mid * s1) % MOD;

        add = (add + ((qa % MOD + MOD) % MOD) * ((qb % MOD + MOD) % MOD) % MOD * cnt) % MOD;

        total += add;
        total %= MOD;
    }

    // subtract triples with s=l=e counted twice
    long long interL = max({A, C, E});
    long long interR = min({B, D, F});
    if (interL <= interR) {
        total -= (interR - interL + 1) % MOD;
        if (total < 0) total += MOD;
    }

    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long sx1, sx2, sy1, sy2;
    long long lx1, lx2, ly1, ly2;
    long long ex1, ex2, ey1, ey2;

    cin >> sx1 >> sx2 >> sy1 >> sy2;
    cin >> lx1 >> lx2 >> ly1 >> ly2;
    cin >> ex1 >> ex2 >> ey1 >> ey2;

    // Manhattan shortest path condition:
    // dist(S,L)+dist(L,E)=dist(S,E)
    // equivalent to:
    // |sx-lx|+|lx-ex|=|sx-ex|  and  |sy-ly|+|ly-ey|=|sy-ey|
    // i.e. lx lies between sx and ex, and ly lies between sy and ey.
    long long cx = countBetween1D(sx1, sx2, lx1, lx2, ex1, ex2);
    long long cy = countBetween1D(sy1, sy2, ly1, ly2, ey1, ey2);

    long long ans = cx * cy % MOD;
    cout << ans % MOD << '\n';
    return 0;
}

