def solve():
    MOD = 10**9 + 7
    input_data = sys.stdin.read().split()
    idx = 0

    H, W = int(input_data[idx]), int(input_data[idx+1]); idx += 2
    # Regions A, B, C each defined by r1,c1,r2,c2
    ra1,ca1,ra2,ca2 = int(input_data[idx]),int(input_data[idx+1]),int(input_data[idx+2]),int(input_data[idx+3]); idx+=4
    rb1,cb1,rb2,cb2 = int(input_data[idx]),int(input_data[idx+1]),int(input_data[idx+2]),int(input_data[idx+3]); idx+=4
    rc1,cc1,rc2,cc2 = int(input_data[idx]),int(input_data[idx+1]),int(input_data[idx+2]),int(input_data[idx+3]); idx+=4

    maxn = H + W + 10
    fact = [1] * (maxn + 1)
    for i in range(1, maxn + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (maxn + 1)
    inv_fact[maxn] = pow(fact[maxn], MOD-2, MOD)
    for i in range(maxn-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def C(n, r):
        if r < 0 or r > n: return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    def paths(r1,c1,r2,c2):
        dr = r2-r1; dc = c2-c1
        if dr < 0 or dc < 0: return 0
        return C(dr+dc, dr)

    ans = 0
    for rs in range(ra1, ra2+1):
        for cs in range(ca1, ca2+1):
            for rl in range(rb1, rb2+1):
                for cl in range(cb1, cb2+1):
                    for re in range(rc1, rc2+1):
                        for ce in range(cc1, cc2+1):
                            p1 = paths(rs,cs,rl,cl)
                            p2 = paths(rl,cl,re,ce)
                            if p1 > 0 and p2 > 0:
                                ans = (ans + p1 * p2) % MOD
    print(ans)

