import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long modPow(long a, long e) {
        long r = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long inv2 = (MOD + 1) / 2;

    // sum_{x=l..r} x
    static long sum1(long l, long r) {
        if (l > r) return 0;
        long cnt = (r - l + 1) % MOD;
        long s = ((l + r) % MOD) * cnt % MOD * inv2 % MOD;
        return s;
    }

    // sum_{x=l..r} x^2
    static long sum2(long l, long r) {
        if (l > r) return 0;
        return (prefix2(r) - prefix2(l - 1) + MOD) % MOD;
    }

    static long inv6 = modPow(6, MOD - 2);

    static long prefix2(long n) {
        if (n <= 0) return 0;
        long a = n % MOD;
        long b = (n + 1) % MOD;
        long c = (2 * (n % MOD) + 1) % MOD;
        return a * b % MOD * c % MOD * inv6 % MOD;
    }

    // Sum over x in [l1,r1], y in [l2,r2] of |x-y|
    static long sumAbs(long l1, long r1, long l2, long r2) {
        if (l1 > r1 || l2 > r2) return 0;

        if (r1 <= l2) {
            long cnt1 = (r1 - l1 + 1) % MOD;
            long cnt2 = (r2 - l2 + 1) % MOD;
            long s1 = sum1(l1, r1);
            long s2 = sum1(l2, r2);
            return (cnt1 * s2 % MOD - cnt2 * s1 % MOD + MOD) % MOD;
        }
        if (r2 <= l1) {
            long cnt1 = (r1 - l1 + 1) % MOD;
            long cnt2 = (r2 - l2 + 1) % MOD;
            long s1 = sum1(l1, r1);
            long s2 = sum1(l2, r2);
            return (cnt2 * s1 % MOD - cnt1 * s2 % MOD + MOD) % MOD;
        }

        long ans = 0;

        // x < y part
        long A1 = l1, B1 = Math.min(r1, l2 - 1);
        if (A1 <= B1) {
            long cntx = (B1 - A1 + 1) % MOD;
            long cnty = (r2 - l2 + 1) % MOD;
            long sx = sum1(A1, B1);
            long sy = sum1(l2, r2);
            ans = (ans + cntx * sy % MOD - cnty * sx % MOD + MOD) % MOD;
        }

        // overlapping part
        long L = Math.max(l1, l2);
        long R = Math.min(r1, r2);
        if (L <= R) {
            // sum over x,y in [L,R] of |x-y|
            long n = R - L + 1;
            long nn = n % MOD;
            long term = nn * ((nn - 1 + MOD) % MOD) % MOD * ((nn + 1) % MOD) % MOD * inv6 % MOD;
            term = term * 2 % MOD;
            ans = (ans + term) % MOD;

            // left overlap x in [L,R], y in [R+1,r2]
            if (R + 1 <= r2) {
                long cntx = (R - L + 1) % MOD;
                long cnty = (r2 - (R + 1) + 1) % MOD;
                long sx = sum1(L, R);
                long sy = sum1(R + 1, r2);
                ans = (ans + cntx * sy % MOD - cnty * sx % MOD + MOD) % MOD;
            }

            // right overlap x in [R+1,r1], y in [L,R]
            if (R + 1 <= r1) {
                long cntx = (r1 - (R + 1) + 1) % MOD;
                long cnty = (R - L + 1) % MOD;
                long sx = sum1(R + 1, r1);
                long sy = sum1(L, R);
                ans = (ans + cnty * sx % MOD - cntx * sy % MOD + MOD) % MOD;
            }
        }

        // x > y part
        long A2 = Math.max(l1, r2 + 1), B2 = r1;
        if (A2 <= B2) {
            long cntx = (B2 - A2 + 1) % MOD;
            long cnty = (r2 - l2 + 1) % MOD;
            long sx = sum1(A2, B2);
            long sy = sum1(l2, r2);
            ans = (ans + cnty * sx % MOD - cntx * sy % MOD + MOD) % MOD;
        }

        return ans % MOD;
    }

    // Count triples (s,m,t) with s in [a,b], m in [c,d], t in [e,f]
    // such that |s-m| + |m-t| = |s-t|, i.e. m lies between s and t.
    // 1D count.
    static long countBetween1D(long a, long b, long c, long d, long e, long f) {
        long[] pts = {a, b + 1, c, d + 1, e, f + 1};
        Arrays.sort(pts);

        long ans = 0;
