    static long intervalSign(long L, long R, long a, long b) {
        if (R < a || b < L) return 0;
        return 1;
    }

    // returns affine p*x + q for count of numbers in [a,b] and <= x, valid on x in [L,R]
    static long[] prefixCoef(long a, long b, long L, long R) {
        if (R < a) return new long[]{0, 0};
        if (L > b) return new long[]{0, (b - a + 1) % MOD};
        if (L >= a && R <= b) {
            // x-a+1
            return new long[]{1, ((-a + 1) % MOD + MOD) % MOD};
        }
        // Since [L,R] is between critical points, only full outside or inside occurs.
        if (R <= b) return new long[]{1, ((-a + 1) % MOD + MOD) % MOD};
        return new long[]{0, (b - a + 1) % MOD};
    }

    // returns affine p*x + q for count of numbers in [a,b] and >= x, valid on x in [L,R]
    static long[] suffixCoef(long a, long b, long L, long R) {
        if (L > b) return new long[]{0, 0};
        if (R < a) return new long[]{0, (b - a + 1) % MOD};
        if (L >= a && R <= b) {
            // b-x+1
            return new long[]{MOD - 1, (b + 1) % MOD};
        }
        if (L >= a) return new long[]{MOD - 1, (b + 1) % MOD};
        return new long[]{0, (b - a + 1) % MOD};
    }

    // (a1*x+b1)*(a2*x+b2) = c2*x^2 + c1*x + c0
    static long[] multiplyAffine(long[] u, long[] v) {
        long a1 = u[0], b1 = u[1], a2 = v[0], b2 = v[1];
        long c2 = a1 * a2 % MOD;
        long c1 = (a1 * b2 + a2 * b1) % MOD;
        long c0 = b1 * b2 % MOD;
        return new long[]{c2, c1, c0};
    }

    static long sumPoly(long[] c, long L, long R) {
        long s2 = sum2(L, R);
        long s1 = sum1(L, R);
        long n = (R - L + 1) % MOD;
        return (c[0] * s2 + c[1] * s1 + c[2] * n) % MOD;
    }

