(x,y,z) in A x B x C such that y is between x and z.

For fixed y, number of pairs (x,z) with x<=y<=z or z<=y<=x:
L(y)=#A elements <= y, R(y)=#A elements >= y
P(y)=#C elements <= y, Q(y)=#C elements >= y
count(y)=L(y)*Q(y)+R(y)*P(y)-eqA(y)*eqC(y)
where eqA(y)=1 if y in A else 0, eqC(y)=1 if y in C else 0,
subtracting double-counted x=z=y.

We need sum over y in B. Since each term is piecewise quadratic/linear over integer y,
we split by all relevant boundaries and sum formulas.

Helper sums over integer interval [l,r]:
sum 1, sum y, sum y^2.
*/

static ll sum1(ll l, ll r) {
    if (l > r) return 0;
    return (r - l + 1) % MOD;
}

static ll sumy(ll l, ll r) {
    if (l > r) return 0;
    ll n = (r - l + 1) % MOD;
    ll s = ((l + r) % MOD) * n % MOD * mod_inv(2) % MOD;
    return s;
}

static ll pref2(ll n) {
    if (n <= 0) return 0;
    ll a = n % MOD;
    ll b = (n + 1) % MOD;
    ll c = (2 * (n % MOD) + 1) % MOD;
    return a * b % MOD * c % MOD * mod_inv(6) % MOD;
}

static ll sumy2(ll l, ll r) {
    if (l > r) return 0;
    ll res = (pref2(r) - pref2(l - 1)) % MOD;
    if (res < 0) res += MOD;
    return res;
}

static ll cnt_le(ll L, ll R, ll y) {
    if (y < L) return 0;
    if (y > R) return R - L + 1;
    return y - L + 1;
}

static ll cnt_ge(ll L, ll R, ll y) {
    if (y < L) return R - L + 1;
    if (y > R) return 0;
    return R - y + 1;
}

/*
On a segment where relative positions to interval endpoints are fixed,
each of L,R,P,Q is either constant or affine in y:
const, y-L+1, R-y+1.
Then count(y) is quadratic; sum via sums of 1,y,y^2.
*/

typedef struct {
    ll a2, a1, a0; // a2*y^2 + a1*y + a0
} Poly;

static Poly mul_lin(ll p1, ll p0, ll q1, ll q0) {
    Poly r;
    r.a2 = (p1 % MOD) * (q1 % MOD) % MOD;
    r.a1 = ((p1 % MOD) * (q0 % MOD) + (p0 % MOD) * (q1 % MOD)) % MOD;
    r.a0 = (p0 % MOD) * (q0 % MOD) % MOD;
    return r;
}

static ll eval_sum_poly(Poly p, ll l, ll r) {
    ll res = 0;
    res = (res + p.a2 * sumy2(l, r)) % MOD;
    res = (res + p.a1 * sumy(l, r)) % MOD;
    res = (res + p.a0 * sum1(l, r)) % MOD;
    return res;
}

static void get_lin_le(ll L, ll R, ll segL, ll segR, ll *c1, ll *c0) {
    // cnt_le(L,R,y) on segment [segL,segR] with no endpoint crossings inside
    if (segR < L) {
        *c1 = 0; *c0 = 0;
    } else if (segL > R) {
        *c1 = 0; *c0 = (R - L + 1) % MOD;
    } else {
        *c1 = 1;
        *c0 = (-L + 1) % MOD;
        if (*c0 < 0) *c0 += MOD;
    }
}

static void get_lin_ge(ll L, ll R, ll segL, ll segR, ll *c1, ll *c0) {
    // cnt_ge(L,R,y)
    if (segR < L) {
        *c1 = 0; *c0 = (R - L + 1) % MOD;
    } else if (segL > R) {
        *c1 = 0; *c0 = 0;
    } else {
        *c1 = MOD - 1; // -1
        *c0 = (R + 1) % MOD;
    }
}

static ll count1D(ll A1, ll A2, ll B1, ll B2, ll C1, ll C2) {
    ll pts[10];
    int m = 0;
    pts[m++] = B1;
    pts[m++] = B2 + 1;
    pts[m++] = A1;
    pts[m++] = A2 + 1;
    pts[m++] = C1;
    pts[m++] = C2 + 1;

    // sort unique
    for (int i = 0; i < m; i++) {
        for (int j = i + 1; j < m; j++) {
            if (pts[i] > pts[j]) {
                ll t = pts[i]; pts[i] = pts[j]; pts[j] = t;
            }
        }
    }
    ll uniq[10];
    int u = 0;
    for (int i = 0; i < m; i++) {
        if (i == 0 || pts[i] != pts[i - 1]) uniq[u++] = pts[i];
    }

    ll ans = 0;
    for (int s = 0; s + 1 < u; s++) {
        ll l = uniq[s];
        ll r = uniq[s + 1] - 1;
        if (l > r) continue;
        if (r < B1 || l > B2) continue;
        if (l < B1) l = B1;
        if (r > B2) r = B2;

        ll l1, l0, r1, r0, p1, p0, q1, q0;
        get_lin_le(A1, A2, l, r, &l1, &l0);
        get_lin_ge(A1, A2, l, r, &r1, &r0);
        get_lin_le(C1, C2, l, r, &p1, &p0);
        get_lin_ge(C1, C2, l, r, &q1, &q0);

        Poly t1 = mul_lin(l1, l0, q1, q0);
        Poly t2 = mul_lin(r1, r0, p1, p0);

        Poly total;
        total.a2 = (t1.a2 + t2.a2) % MOD;
        total.a1 = (t1.a1 + t2.a1) % MOD;
        total.a0 = (t1.a0 + t2.a0) % MOD;

        ans = (ans + eval_sum_poly(total, l, r)) % MOD;

        // subtract eqA(y)*eqC(y) over this segment:
        ll il = l > (A1 > C1 ? A1 : C1) ? l : (A1 > C1 ? A1 : C1);
        ll ir = r < (A2 < C2 ? A2 : C2) ? r : (A2 < C2 ? A2 : C2);
        if (il <= ir) {
            ans = (ans - (ir - il + 1)) % MOD;
            if (ans < 0) ans += MOD;
        }
    }
    return ans;
}

int main(void) {
    ll a,b,c,d,e,f,g,h,i,j,k,l;
    if (scanf("%lld%lld%lld%lld", &a,&b,&c,&d) != 4) return 0;
    if (scanf("%lld%lld%lld%lld", &e,&f,&g,&h) != 4) return 0;
    if (scanf("%lld%lld%lld%lld", &i,&j,&k,&l) != 4) return 0;

    ll x = count1D(a,b,e,f,i,j);
    ll y = count1D(c,d,g,h,k,l);
    ll ans = x * y % MOD;
    printf("%lld\n", ans);
    return 0;
}
